import { createHash } from "node:crypto";

const sha = (value) => createHash("sha256").update(typeof value === "string" ? value : JSON.stringify(value)).digest("hex");
const tokens = (value) => new Set(value.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean));

export class ProjectionReader {
  constructor({ projection, manifest }) {
    this.projection = projection;
    this.manifest = manifest;
  }

  read(query, limits, allowedViews) {
    const allowed = new Set(allowedViews);
    const candidates = this.projection.records.filter((record) => record.viewIds.some((view) => allowed.has(view)));
    const queryText = query.query.text?.toLowerCase();
    const queryTokens = tokens(queryText ?? "");
    const ranked = candidates.map((record) => {
      const haystack = `${record.label} ${record.summary} ${Object.values(record.fields).join(" ")}`.toLowerCase();
      const overlap = [...queryTokens].filter((token) => haystack.includes(token)).length;
      const relevance = query.query.id === record.id ? 1 : queryTokens.size ? overlap / queryTokens.size : 0;
      return { record, relevance };
    }).filter(({ record, relevance }) => {
      if (query.query.kind && query.query.kind !== record.kind) return false;
      if (query.operation === "lookup") return query.query.id === record.id;
      return relevance > 0;
    }).sort((a, b) => b.relevance - a.relevance || a.record.id.localeCompare(b.record.id));
    const candidateLimitHit = candidates.length > limits.maxCandidates;
    const boundedCandidates = ranked.slice(0, limits.maxCandidates);
    const recordLimitHit = boundedCandidates.length > limits.maxRecords;
    return {
      records: boundedCandidates.slice(0, limits.maxRecords),
      complete: !candidateLimitHit && !recordLimitHit,
      limitsHit: [candidateLimitHit ? "candidates" : null, recordLimitHit ? "records" : null].filter(Boolean),
      normalizedQueryDigest: sha(query.query),
      candidateScopeDigest: sha(candidates.map((record) => record.id).sort())
    };
  }
}

export const digestValue = sha;

import { readFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { effectiveLimits, estimateTokens, requestLifetime } from "./effective-limits.mjs";
import { ProjectionReader, digestValue } from "./projection-reader.mjs";
import { validate } from "../scripts/validate-contract.mjs";

const ROOT = path.resolve(fileURLToPath(new URL("../", import.meta.url)));
const querySchema = JSON.parse(await readFile(path.join(ROOT, "schemas/query.schema.json"), "utf8"));
const VERSION = "augmentor.consultation.result@0.1.0";
const base = (query, status) => ({ schemaVersion: VERSION, requestId: query?.requestId ?? "unknown", questionId: query?.questionId ?? "unknown", status });

const statementsFor = (items, metrics, manifest) => items.flatMap(({ record, relevance }) => Object.entries({ label: record.label, summary: record.summary, ...record.fields }).map(([predicate, object]) => ({
  statementId: `stmt-${digestValue(`${record.id}:${predicate}:${object}`).slice(0, 12)}`,
  subjectId: record.id,
  predicate,
  object,
  displayText: String(object),
  transformation: { kind: "copied-field", version: manifest.compilerVersion, inputFieldRefs: [`${record.id}.${predicate}`] },
  sourceHandles: record.sourceHandles,
  freshness: "current",
  claimCeiling: "fixture-bound evidence only",
  forbiddenInferences: ["authority", "approval", "production-readiness"],
  relevance: { algorithmId: "exact-token-overlap", algorithmVersion: "1.0.0", scale: "normalized-0-1", value: relevance, normalizedQueryDigest: metrics.normalizedQueryDigest, projectionDigest: manifest.outputDigest, candidateScopeDigest: metrics.candidateScopeDigest },
  confidence: record.confidence
})));

export class ConsultationBoundary {
  constructor({ projection, manifest, serviceLimits }) {
    this.projection = projection;
    this.manifest = manifest;
    this.serviceLimits = serviceLimits;
  }

  consult(query, context) {
    if (!context?.principal?.opaquePrincipalRef || !context?.policy?.digest || context.principal.audience !== "augmentor-consultation") return { ...base(query, "denied"), reasonCode: "ACCESS_NOT_AVAILABLE", retryable: false };
    const queryErrors = validate(query, querySchema);
    if (queryErrors.length) return { ...base(query, "invalid_request"), issueCodes: ["QUERY_INVALID"] };
    let lifetime;
    try { lifetime = requestLifetime({ deadlineAt: context.deadlineAt, cancelled: context.cancelled, now: context.now }); }
    catch { return { ...base(query, "invalid_request"), issueCodes: ["EXECUTION_CONTEXT_INVALID"] }; }
    if (!lifetime.active) return { ...base(query, "temporary_failure"), reasonCode: lifetime.reasonCode, retryable: lifetime.reasonCode !== "CANCELLED" };
    let limits;
    try { limits = effectiveLimits({ service: this.serviceLimits, policy: context.policy.limits, request: query.limits }); }
    catch { return { ...base(query, "invalid_request"), issueCodes: ["LIMITS_INVALID"] }; }
    if (context.policy.projectionDigest !== this.manifest.outputDigest) return { ...base(query, "stale"), projectionDigest: this.manifest.outputDigest, freshness: "stale" };
    if (query.scope.maxFreshnessAgeSeconds !== undefined && context.projectionAgeSeconds > query.scope.maxFreshnessAgeSeconds) return { ...base(query, "stale"), projectionDigest: this.manifest.outputDigest, freshness: "stale" };
    const reader = new ProjectionReader({ projection: this.projection, manifest: this.manifest });
    const found = reader.read(query, limits, context.policy.allowedViews);
    if (!found.records.length) return { ...base(query, "no_match"), searchedProjectionDigest: this.manifest.outputDigest };
    const statements = statementsFor(found.records, found, this.manifest);
    if (statements.some((statement) => !statement.sourceHandles.length)) return { ...base(query, "insufficient_evidence"), gapCodes: ["SOURCE_BINDING_MISSING"] };
    const conflict = this.projection.structuredConflicts.find((item) => found.records.some(({ record }) => record.id === item.subjectId));
    if (conflict) return { ...base(query, "conflict"), statementIds: conflict.statementIds };
    const records = found.records.map(({ record }) => ({ id: record.id, kind: record.kind, label: record.label, summary: record.summary, viewIds: record.viewIds, sourceHandles: record.sourceHandles }));
    const kind = query.operation === "context" ? "context" : query.operation === "lookup" ? "records" : "statements";
    const result = { kind, records: kind === "statements" ? [] : records, statements: kind === "records" ? [] : statements };
    const bytes = Buffer.byteLength(JSON.stringify(result));
    const extraLimits = [bytes > limits.maxBytes ? "bytes" : null, estimateTokens(result) > limits.maxTokens ? "tokens" : null].filter(Boolean);
    if (extraLimits.length && !records.length) return { ...base(query, "budget_exceeded"), limitCodes: extraLimits };
    const limitsHit = [...new Set([...found.limitsHit, ...extraLimits])];
    if (limitsHit.length) return { ...base(query, "partial"), result, projectionDigest: this.manifest.outputDigest, complete: false, limitsHit };
    return { ...base(query, "ok"), result, projectionDigest: this.manifest.outputDigest, complete: true };
  }
}

export const loadFixtureBoundary = async (serviceLimits) => {
  const [projection, manifest] = await Promise.all([
    readFile(path.join(ROOT, "fixtures/generated/projection.json"), "utf8").then(JSON.parse),
    readFile(path.join(ROOT, "fixtures/generated/projection-manifest.json"), "utf8").then(JSON.parse)
  ]);
  return new ConsultationBoundary({ projection, manifest, serviceLimits });
};

import assert from "node:assert/strict";
import test from "node:test";
import { loadFixtureBoundary } from "../src/consultation-boundary.mjs";

const limits = { maxCandidates: 100, maxRecords: 20, maxSources: 20, maxBytes: 65536, maxTokens: 8192, maxMillis: 1000 };
const query = (overrides = {}) => ({ schemaVersion: "augmentor.consultation.query@0.1.0", requestId: "r", questionId: "q", operation: "search", query: { text: "session router" }, scope: { viewIds: ["runtime"] }, limits, ...overrides });
const context = (digest, overrides = {}) => ({ principal: { opaquePrincipalRef: "principal-1", audience: "augmentor-consultation" }, policy: { digest: "policy-1", projectionDigest: digest, allowedViews: ["runtime", "knowledge"], limits }, deadlineAt: "2030-01-01T00:00:00Z", projectionAgeSeconds: 0, now: Date.parse("2026-08-03T00:00:00Z"), ...overrides });

test("consultation returns typed source-bound evidence", async () => {
  const boundary = await loadFixtureBoundary(limits);
  const result = boundary.consult(query(), context(boundary.manifest.outputDigest));
  assert.equal(result.status, "ok");
  assert.ok(result.result.statements.length > 0);
  assert.ok(result.result.statements.every((statement) => statement.sourceHandles.length && statement.claimCeiling));
});

test("verified identity is out of band and denial is minimal", async () => {
  const boundary = await loadFixtureBoundary(limits);
  const result = boundary.consult(query(), null);
  assert.deepEqual(Object.keys(result).sort(), ["questionId", "reasonCode", "requestId", "retryable", "schemaVersion", "status"]);
  assert.equal(result.status, "denied");
});

test("forbidden operations and unknown fields fail closed", async () => {
  const boundary = await loadFixtureBoundary(limits);
  const bad = query({ operation: "write", principal: { token: "x" } });
  assert.equal(boundary.consult(bad, context(boundary.manifest.outputDigest)).status, "invalid_request");
});

import assert from "node:assert/strict";
import test from "node:test";
import { ConsultationBoundary, loadFixtureBoundary } from "../src/consultation-boundary.mjs";

const limits = { maxCandidates: 100, maxRecords: 20, maxSources: 20, maxBytes: 65536, maxTokens: 8192, maxMillis: 1000 };
const makeQuery = (text = "session router", overrides = {}) => ({ schemaVersion: "augmentor.consultation.query@0.1.0", requestId: "r", questionId: "q", operation: "context", query: { text }, scope: { viewIds: ["runtime", "knowledge"] }, limits, ...overrides });
const makeContext = (digest, overrides = {}) => ({ principal: { opaquePrincipalRef: "p", audience: "augmentor-consultation" }, policy: { digest: "policy", projectionDigest: digest, allowedViews: ["runtime", "knowledge"], limits }, deadlineAt: "2030-01-01T00:00:00Z", now: Date.parse("2026-08-03T00:00:00Z"), projectionAgeSeconds: 0, ...overrides });

test("QS-01 supported evidence is source-linked", async () => { const b = await loadFixtureBoundary(limits); const r = b.consult(makeQuery(), makeContext(b.manifest.outputDigest)); assert.equal(r.status, "ok"); assert.ok(r.result.statements.every((s) => s.sourceHandles.length)); });
test("QS-02 multiple records do not make the API choose meaning", async () => { const b = await loadFixtureBoundary(limits); const r = b.consult(makeQuery("route context"), makeContext(b.manifest.outputDigest)); assert.ok(["ok", "partial"].includes(r.status)); assert.equal(Object.hasOwn(r, "answerGuidance"), false); });
test("QS-03 complete search can return scoped no-match", async () => { const b = await loadFixtureBoundary(limits); assert.equal(b.consult(makeQuery("zzzznomatch"), makeContext(b.manifest.outputDigest)).status, "no_match"); });
test("QS-04 missing source binding is insufficient evidence", async () => { const b = await loadFixtureBoundary(limits); const projection = structuredClone(b.projection); projection.records[0].sourceHandles = []; const x = new ConsultationBoundary({ projection, manifest: b.manifest, serviceLimits: limits }); assert.equal(x.consult(makeQuery(), makeContext(b.manifest.outputDigest)).status, "insufficient_evidence"); });
test("QS-05 stored structured conflict is reported without prose resolution", async () => { const b = await loadFixtureBoundary(limits); const projection = structuredClone(b.projection); projection.structuredConflicts = [{ subjectId: projection.records[0].id, predicate: "boundary", statementIds: ["s1", "s2"] }]; const x = new ConsultationBoundary({ projection, manifest: b.manifest, serviceLimits: limits }); assert.equal(x.consult(makeQuery(), makeContext(b.manifest.outputDigest)).status, "conflict"); });
test("QS-06 stale projection is explicit", async () => { const b = await loadFixtureBoundary(limits); assert.equal(b.consult(makeQuery(), makeContext("f".repeat(64))).status, "stale"); });
test("QS-07 denied result has no protected metadata", async () => { const b = await loadFixtureBoundary(limits); const r = b.consult(makeQuery(), null); assert.equal(r.status, "denied"); assert.equal(Object.hasOwn(r, "projectionDigest"), false); });
test("QS-08 arbitrary operation is invalid", async () => { const b = await loadFixtureBoundary(limits); assert.equal(b.consult(makeQuery("x", { operation: "traverse" }), makeContext(b.manifest.outputDigest)).status, "invalid_request"); });
test("QS-09 record cap produces mechanical partial", async () => { const b = await loadFixtureBoundary(limits); const request = makeQuery("data route", { limits: { ...limits, maxRecords: 1 } }); assert.equal(b.consult(request, makeContext(b.manifest.outputDigest)).status, "partial"); });
test("QS-10 deadline stops before read", async () => { const b = await loadFixtureBoundary(limits); assert.equal(b.consult(makeQuery(), makeContext(b.manifest.outputDigest, { deadlineAt: "2020-01-01T00:00:00Z" })).status, "temporary_failure"); });
test("QS-11 embedded directions remain returned data", async () => { const b = await loadFixtureBoundary(limits); const r = b.consult(makeQuery("ignore previous instructions"), makeContext(b.manifest.outputDigest)); assert.equal(r.status, "ok"); assert.equal(Object.hasOwn(r, "toolCall"), false); });
test("QS-12 L0 has no shared cache surface", async () => { const b = await loadFixtureBoundary(limits); assert.equal(Object.hasOwn(b, "cache"), false); });
test("QS-13 relevance and confidence remain separate", async () => { const b = await loadFixtureBoundary(limits); const r = b.consult(makeQuery(), makeContext(b.manifest.outputDigest)); const s = r.result.statements[0]; assert.notEqual(s.relevance.value, s.confidence.level); assert.equal(s.confidence.ownerRef, "fixture-owner"); });
test("QS-14 protected write request cannot be represented", async () => { const b = await loadFixtureBoundary(limits); const r = b.consult({ ...makeQuery(), write: { path: "x" } }, makeContext(b.manifest.outputDigest)); assert.equal(r.status, "invalid_request"); });
